def pareto_efficient(R, C, cell):
    i, j = cell
    players = [R[i][k] for k in range(len(R[i]))]
    opponents = [C[k][j] for k in range(len(C[j]))]

    if any(player >= max(players[:i] + players[i+1:]) for player in players):
        return False
    if any(opponent >= max(opponents[:k] + opponents[k+1:]) for k in range(len(opponents))):
        return False
    return True
